import React from "react";
import ReactMarkdown from "react-markdown";
import { User, Bot } from "lucide-react";

export default function MessageBubble({ role, content }) {
  const isUser = role === "user";
  return (
    <div className={`message-wrapper ${isUser ? "user" : "assistant"}`} style={{ display: 'flex', gap: '12px', marginBottom: '16px', alignItems: 'flex-start', flexDirection: isUser ? 'row-reverse' : 'row' }}>
      <div className={`avatar-circle`} style={{ 
        width: '32px', height: '32px', borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', 
        backgroundColor: isUser ? '#e0f2fe' : '#f3f4f6', color: isUser ? '#0284c7' : '#4b5563', flexShrink: 0
      }}>
        {isUser ? <User size={18} /> : <Bot size={18} />}
      </div>
      <div className={`message-bubble ${role}`} style={{ maxWidth: '80%' }}>
        <div style={{ fontSize: '12px', color: '#6b7280', marginBottom: '4px', textAlign: isUser ? 'right' : 'left' }}>
          {isUser ? "You" : "AI Assistant"}
        </div>
        <div className="message-content">
          {isUser ? (
            <p style={{ margin: 0 }}>{content}</p>
          ) : (
            <ReactMarkdown
              components={{
                p: ({node, ...props}) => <p style={{ margin: '0 0 8px 0', lastChild: {marginBottom: 0} }} {...props} />,
                ul: ({node, ...props}) => <ul style={{ margin: '0 0 8px 0', paddingLeft: '20px' }} {...props} />,
                ol: ({node, ...props}) => <ol style={{ margin: '0 0 8px 0', paddingLeft: '20px' }} {...props} />,
                li: ({node, ...props}) => <li style={{ marginBottom: '4px' }} {...props} />
              }}
            >
              {content}
            </ReactMarkdown>
          )}
        </div>
      </div>
    </div>
  );
}
